#include <string>
#include <vector>
#include <cmath>
#include <algorithm>

class Solution {
    bool isConsecutive(char a, char b) {
        int diff = std::abs(a - b);
        return diff == 1 || diff == 25;
    }

public:
    std::string lexicographicallySmallestString(std::string s) {
        int n = s.size();
        std::vector<std::vector<std::string>> dp(n + 1, std::vector<std::string>(n + 1, ""));

        for (int d = 1; d <= n; ++d) {
            for (int i = 0; i + d <= n; ++i) {
                int j = i + d;
                std::string min_str = s[i] + dp[i + 1][j];
                for (int k = i + 1; k < j; ++k) {
                    if (isConsecutive(s[i], s[k]) && dp[i + 1][k].empty()) {
                        std::string cand = dp[k + 1][j];
                        if (min_str.empty() || cand < min_str) {
                            min_str = cand;
                        }
                    }
                }
                dp[i][j] = min_str;
            }
        }

        return dp[0][n];
    }
};

class Solution {
    private boolean isConsecutive(char a, char b) {
        int diff = Math.abs(a - b);
        return diff == 1 || diff == 25;
    }

    public String lexicographicallySmallestString(String s) {
        int n = s.length();
        String[][] dp = new String[n + 1][n + 1];
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= n; ++j) {
                dp[i][j] = "";
            }
        }

        for (int d = 1; d <= n; ++d) {
            for (int i = 0; i + d <= n; ++i) {
                int j = i + d;
                String minStr = s.charAt(i) + dp[i + 1][j];
                for (int k = i + 1; k < j; ++k) {
                    if (isConsecutive(s.charAt(i), s.charAt(k)) && dp[i + 1][k].isEmpty()) {
                        String cand = dp[k + 1][j];
                        if (minStr.isEmpty() || cand.compareTo(minStr) < 0) {
                            minStr = cand;
                        }
                    }
                }
                dp[i][j] = minStr;
            }
        }

        return dp[0][n];
    }
}

