var lexicographicallySmallestString = function(s) {
    const n = s.length;
    const dp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(""));

    function isConsecutive(a, b) {
        const diff = Math.abs(a.charCodeAt(0) - b.charCodeAt(0));
        return diff === 1 || diff === 25;
    }

    for (let d = 1; d <= n; ++d) {
        for (let i = 0; i + d <= n; ++i) {
            const j = i + d;
            let minStr = s[i] + dp[i + 1][j];
            for (let k = i + 1; k < j; ++k) {
                if (isConsecutive(s[i], s[k]) && dp[i + 1][k] === "") {
                    const cand = dp[k + 1][j];
                    if (minStr === "" || cand < minStr) {
                        minStr = cand;
                    }
                }
            }
            dp[i][j] = minStr;
        }
    }

    return dp[0][n];
};
